const T = (t, c, m, mini, bias = -1, mech = null, quota = 0) => ({ moves: m, targetTile: t, targetCount: c, biasTile: bias, mini, mechanic: mech, quota });
const SCHAPTERS = [
  { n: 'S1', title: 'La mattina sbagliata', desc: 'Ti svegli in un mondo dove Hana non è mai morta. Nessuno ti riconosce. Tranne Mugi.', eps: ['s1', 's2', 's3', 's4', 's5'] },
  { n: 'S2', title: 'Potatura', desc: 'Insegnare alla nonna, curare la bambina, potare il passato. Poi scegliere il mattino.', eps: ['s6', 's7', 's8', 's9', 's10'] },
  { n: 'S3', title: 'Radici Profonde', desc: 'Il mondo del sogno continua anche da sveglia. La bambina cresce, il Giardiniere parla di più.', eps: ['s11', 's12', 's13', 's14', 's15'] },
  { n: 'S4', title: 'Il Seme', desc: 'Piantate qualcosa insieme. Quello che cresce non è quello che avete seminato.', eps: ['s16', 's17', 's18', 's19', 's20'] },
  { n: 'S5', title: 'Petali Sopra', desc: 'Il sogno chiede il conto. Le schiume più alte, le scelte più vere.', eps: ['s21', 's22', 's23', 's24', 's25'] },
];
const SSTORY = [
{id:'s1',chap:'S1',ep:1,kicker:'Sak.1-1 · Risveglio',title:'Il locale sbagliato',text:`Ti svegli sul tatami del retrobottega. Profumo di legna e sakura. Dal bancone, una voce impossibile: Hana, settantenne, schiena dritta, che frulla e brontola.\n\n"Tu chi sei? E quello cos'è?" indica Mugi, che hai nella borsa. Mugi ringhia — non a lei. Al suo stesso riflesso: sul bancone c'è un altro chasen, identico, fermo.\n\nLe tue mani tremano. Le sue no. Il mondo è quello giusto con una cucchiaiata di troppo.`,cliff:`Hana ti squadra: "Hai le mie mani. Spiegami. Dopo aver lavato le tazze."`,choiceA:{label:'«Sono tua nipote. Da un’altra pioggia.»',effect:'coraggio'},choiceB:{label:'Lavi le tazze in silenzio',effect:'dolcezza'},level:T(0,12,26,'awa'),letter:`Nota di Hana viva — "Chi entra senza bussare lava le tazze. Regola prima."`,ps:{coraggio:"Hai detto: sono tua nipote, e io ti ho voluto credere. Ma solo dopo le tazze: la regola non si sospende.",dolcezza:"Hai lavato le tazze in silenzio. Io non ho chiesto niente: ho guardato le mani, e sapevo da dove venivi."},threads:['giardiniere']},
{id:'s2',chap:'S1',ep:2,kicker:'Sak.1-2 · La ladra',title:'La ladra del vapore',text:`Hana ti ha ribattezzata "la ladra del vapore" e ti mette alla prova: un cliente che piange, uno yuzu che sveglia.\n\nLe tue mani sanno già tutto — le sue ricette, i suoi gesti. Lei ti guarda frullare e impallidisce: "Chi ti ha insegnato? Quella M... la faccio solo io."\n\nNon finisce la frase. Il vapore sale dritto, come a nascondervi.`,cliff:`"Domani torni. Con quel coso che ringhia," dice indicando Mugi. È quasi un invito.`,choiceA:{label:'«Tornerò. Ho molto da rubare.»',effect:'coraggio'},choiceB:{label:'«Grazie per lo yuzu.»',effect:'dolcezza'},level:T(2,14,26,'latte'),letter:`Nota di Hana viva — "Frulla come me. Sospetto come me. Indagherò."`,ps:{coraggio:"Hai detto: tornerò, ho molto da rubare. Ho cambiato le serrature due volte, e la chiave l'ho lasciata lì.",dolcezza:"Grazie per lo yuzu, hai detto. Io l'avevo messo lì apposta: è l'unico modo che conosco per sapere chi sei."},threads:['ricetta']},
{id:'s3',chap:'S1',ep:3,kicker:'Sak.1-3 · La bambina',title:'Otto anni e un chasen',text:`Una bambina di otto anni — TU a otto anni, nei vestiti della festa — ti ruba il chasen dal tavolo e scappa ridendo in giardino.\n\nLa rincorri tra i sakura in fiore. Cade, si sbuccia un ginocchio, non piange: "Nonna dice che il tè aspetta e le ginocchia no."\n\nLe insegni a frullare piano. Le sue mani tremano come le tue. Le tieni da dietro, come Hana fece con te. Il cerchio si chiude e si riapre.`,cliff:`"Resta a cena," dice la bambina. "Nonna fa il mochi. Tu sembri una che ha fame da anni."`,choiceA:{label:'Resti a cena (e piangi nel mochi)',effect:'dolcezza'},choiceB:{label:'«Devo capire dove sono.»',effect:'coraggio'},level:T(0,15,26,'awa'),letter:`Disegno della bambina — tu grande dentro una tazza, con scritto "la ladra buona".`,ps:{dolcezza:"Se sei restata a cena, hai pianto nel mochi. Ho fatto finta di niente: è la seconda volta che ti vedo.",coraggio:"Hai detto: devo capire dove sono. Io ti ho dato il chasen lo stesso: capire può aspettare, le mani no."},threads:['aoi-bimba']},
{id:'s4',chap:'S1',ep:4,kicker:'Sak.1-4 · Notte',title:'Il Giardiniere',text:`Di notte il giardino profuma diverso. Un uomo col cappello di paglia annaffia i sakura a lume di lanterna.\n\n"Annaffio quando nessuno guarda. I fiori sono timidi." Ti chiama per nome. Aoi. Tu non glielo hai mai detto.\n\n"Qui tutti sanno il tuo nome," sorride senza voltarsi. "È il resto che non sappiamo." Canticchia la canzone che Hana canta frullando.`,cliff:`Sparisce tra gli alberi prima che tu possa chiedere. Resta una pozzanghera a forma di ombrello.`,choiceA:{label:'Lo segui tra gli alberi',effect:'coraggio'},choiceB:{label:'Resti con la pozzanghera',effect:'dolcezza'},level:T(3,15,25,'respiro'),letter:`Foglia secca — sul retro, grafia ignota: "Di notte i nomi pesano meno."`,ps:{coraggio:"Hai seguito tra gli alberi, e le piante si sono aperte. Io, la mattina dopo, ho trovato le tue scarpe bagnate.",dolcezza:"Se sei restata con la pozzanghera fino a mezzanotte, era una mappa. Io l'ho vista e ho pensato: è già di casa."},threads:['giardiniere']},
{id:'s5',chap:'S1',ep:5,kicker:'Sak.1-5 · Soglia',title:'La lettera mai scritta',text:`Hana ti chiama all’alba, stravolta. Sul bancone: una lettera con la SUA grafia, che lei giura di non aver mai scritto.\n\n"Qualunque tazza sceglierai, io sarò nel vapore. H."\n\nÈ la lettera 25. La tua. Del tuo mondo. "Spiegami," dice Hana, e per la prima volta la sua voce trema. "Subito. Ti prego."\n\nLe racconti tutto: la morte, il debito, Takeshi, la pioggia. Lei ascolta senza interrompere, poi ti abbraccia come solo le nonne sanno.`,cliff:`"Allora resti," dice. "Finché non capiamo. E intanto mi insegni quel koicha che non ricordo più."`,choiceA:{label:'«Resto. E ti insegno tutto.»',effect:'dolcezza'},choiceB:{label:'«Resto. Ma ho paura.»',effect:'coraggio'},level:T(1,16,26,'latte'),letter:`Lettera impossibile — la 25, qui, adesso. Il vapore sa viaggiare.`,ps:{dolcezza:"Hai detto: resto, e ti insegno tutto. Ho iniziato dal koicha del '64: era l'unico che non ricordavo.",coraggio:"Hai detto: resto, ma ho paura. Io avevo paura anche. Solo che la mia era di essere quella che resta."},threads:['ricetta']},
{id:'s6',chap:'S2',ep:1,kicker:'Sak.2-1 · Ricetta',title:'Il koicha del ’64',text:`Hana viva ha dimenticato la ricetta del koicha del 1964 — quella di lei ventenne e Takeshi ragazzo. Proprio quella che tu conosci a memoria.\n\nGliela insegni cucchiaio dopo cucchiaio. Lei, la maestra, prende appunti come una scolara. Ogni tanto ride: "Ma io ero così brava?"\n\n"Sì, nonna. Eri così."`,cliff:`Assaggia, chiude gli occhi: "È lui. È esattamente lui. Come fai a saperlo?"`,choiceA:{label:'«Me l’ha insegnato tu. Altrove.»',effect:'dolcezza'},choiceB:{label:'«Le mani ricordano.»',effect:'coraggio'},level:T(2,17,27,'latte'),letter:`Appunti di Hana — "Il ’64: denso, amaro, due mochi. Come l’amore vero."`,ps:{dolcezza:"Hai detto: me l'ha insegnato tu, altrove. La stessa mano, due mondi: con certe cose non serve parlare.",coraggio:"Hai detto: le mani ricordano. Ti ho guardata frullare e ho pensato che le avessi viste in un sogno, ieri."},threads:['aoi-bimba']},
{id:'s7',chap:'S2',ep:2,kicker:'Sak.2-2 · Specchio',title:'Febbre allo specchio',text:`La bambina ha la febbre a 39. Febbre a 39. Come te nel Cap.3-3, ma stavolta sei TU quella con la mano sulla fronte.\n\nHana vuole tenere aperto. Tu vuoi chiudere. Litigate per amore — litigate IDENTICA a quella con Ren, e ridi piangendo a metà frase.\n\nHana ti guarda strano: "Ridi?" "Scusa. Déjà-vu."`,cliff:`La bambina dorme. Hana dorme sulla sedia. Tu vegli entrambe, chasen in mano come una spada.`,choiceA:{label:'Vegli tutta la notte',effect:'coraggio'},choiceB:{label:'Canti piano come Hana',effect:'dolcezza'},level:T(5,17,27,'respiro'),letter:`Termometro — 36.8 al mattino. "Le nonne guariscono tutto. Anche le nipoti impossibili."`,ps:{coraggio:`Sono sveglia anch'io, dall'altra parte della stanza. Non ti vegliavo: vegliavamo in due. Riposa.`,
        dolcezza:`Se le hai cantato piano, l'ha sentito tutta la casa. Io cantavo così a tua madre. È ereditario.`},threads:['giardiniere']},
{id:'s8',chap:'S2',ep:3,kicker:'Sak.2-3 · Duello',title:'Duello madre-figlia',text:`Hana ti sfida a duello di schiuma: nonna contro nipote venuta dal futuro, Yuki-bambina-no — qui il giudice è Aoi bambina con palette da 1 a 10.\n\n"Vediamo se nel tuo mondo frullano o solo piangono." Tre tazze a testa, sakura che nevica nel giardino.\n\nPareggio, ovviamente. La bambina alza due 10. Hana sbuffa: "Comprata." E ti abbraccia forte.`,cliff:`"Qualunque mondo sia il tuo," sussurra Hana, "lì mi manchi. Lo sento."`,choiceA:{label:'«Anche tu mi manchi. Sempre.»',effect:'dolcezza'},choiceB:{label:'«Tornerò a trovarti. Promesso.»',effect:'coraggio'},level:T(0,18,27,'awa'),letter:`Palette della bambina — due 10 e un cuore disegnato sopra.`,ps:{dolcezza:"Hai detto: anche tu mi manchi, sempre. Io e la bambina abbiamo fatto metà e metà: due '10' sul foglio.",coraggio:"Hai detto: tornerò a trovarti, promesso. Ho risposto: porta la bambina. Una promessa con qualcuno dentro pesa."},threads:['ricetta']},
{id:'s9',chap:'S2',ep:4,kicker:'Sak.2-4 · Potatura',title:'Il sakura vecchio',text:`Il Giardiniere pota il grande sakura del giardino. Lo guardi lavorare: ogni taglio è una carezza.\n\n"Ho piantato quest’albero il giorno dell’apertura. Avevo la tua età." Sessant’anni fa. Ma lui non ne dimostra quaranta.\n\n"Chi sei?" chiedi. Alza il cappello quel tanto che basta: un sorriso che conosci, occhi color tè freddo. Il cappello torna giù. "Il giardiniere."`,cliff:`Quella notte piove — qui piove piano, profuma di sakura. Domani dovrai scegliere.`,choiceA:{label:'«Resta. Ti prego, resta.» (a lui? al mondo?)',effect:'dolcezza'},choiceB:{label:'Prepari lo zaino in silenzio',effect:'coraggio'},level:T(3,19,28,'respiro'),letter:`Petalo potato — "Potare non è tagliare. È scegliere cosa fiorisce."`,ps:{dolcezza:"Hai detto: resta, ti prego. Io ho potato il ramo che ombrava il tè e ho lasciato stare: potare è anche questo.",coraggio:"Hai preparato lo zaino in silenzio. Io ho fatto il tè come se niente fosse: il tè serve anche per tacere."},threads:['aoi-bimba']},
{id:'s10',chap:'S2',ep:5,kicker:'Sak.2-5 · Mattino',title:'Scegli il mattino',text:`Alba rosa. Hana, la bambina, il Giardiniere (da lontano), Mugi che non ringhia più al suo doppio — ci gioca.\n\nHana ti porge una tazza: dentro, schiuma perfetta con un cuore. "L’hai fatta tu, stanotte, dormendo. Le mani sognano, a quanto pare."\n\nLa bevi. Sa di tutti i mattini possibili. Ora scegli in quale svegliarti domani.`,cliff:`Il vapore sale. Dritto nel tuo mondo — o in cerchio, qui. Il chasen non trema più.`,choiceA:{label:'🌸 RADICE SOGNATA — resto qui, nipote ritrovata',effect:'finale-radice-sognata'},choiceB:{label:'🌧️ PIOGGIA VERA — mi sveglio, e porto tutto con me',effect:'finale-pioggia-vera'},level:T(2,20,28,'latte'),letter:`Ultimo petalo — "Qualunque mattino sceglierai, io sarò nel vapore. H. (tutte le H.)"`,finaleNote:'Ultima scelta di Sakura Eterna: RESTARE nel sogno o SVEGLIARSI con tutto nel cuore. 🌸',threads:['giardiniere','ricetta','aoi-bimba']},
/* S3 — Radici Profonde */
{id:'s11',chap:'S3',ep:1,kicker:'Sak.3-1 · Ritorno',title:'Il sogno continua',text:`Dopo la scelta del mattino — qualunque sia stata — il sogno non finisce: continua di lato, come un fiume che si sdoppia. Hana viva ti aspetta al bancone come ogni mattina.\n\n"Hai dormito male. Hai parlato nel sonno. Dicevi 'pioggia'." Le sorridi: "Sognavo un altro locale. Uguale a questo, ma bagnato."\n\nLa bambina è cresciuta di un’estate: ti arriva alla spalla, frulla quasi bene. Mugi gioca col suo doppio senza più ringhiare.`,cliff:`Il Giardiniere lascia sulla porta un sacchetto di semi: "Piantali con lei. È ora."`,choiceA:{label:'Piantate i semi con la bambina',effect:'dolcezza'},choiceB:{label:'Chiedi prima cosa sono',effect:'coraggio'},level:T(0,18,27,'awa',-1,'bloom'),letter:`Sacchetto di semi — senza etichetta. Solo un fiocco rosa.`,ps:{dolcezza:"Avete piantato i semi con la bambina, sporche di terra in due. Io guardavo dalla porta e non ho detto niente.",coraggio:"Hai chiesto prima cosa sono: semi. Ti ho risposto solo quello, perché le domande vere vanno una alla volta."},threads:['aoi-bimba']},
{id:'s12',chap:'S3',ep:2,kicker:'Sak.3-2 · Quaderno',title:'Il quaderno delle due',text:`Tu e Hana iniziate un quaderno condiviso: lei scrive le ricette che ricorda, tu quelle che sai dal futuro. A pagina 10 le grafie si confondono.\n\n"Questa l’ho scritta io o tu?" ride Hana. "Tutte e due. Come tutto, qui."\n\nLa bambina ci disegna sopra: una tazza con due manici. "Così la teniamo insieme senza litigare."`,cliff:`A pagina 20 trovate una ricetta che nessuna delle due ha scritto: koicha del ’64, grafia del Giardiniere.`,choiceA:{label:'«Lui sa. Dobbiamo chiedergli.»',effect:'coraggio'},choiceB:{label:'Copiate la ricetta in silenzio',effect:'dolcezza'},level:T(2,18,27,'latte',-1,'bloom'),letter:`Pagina 20 — il ’64 in grafia ignota. Il quaderno sa più di voi.`,ps:{coraggio:"Hai detto: lui sa, dobbiamo chiedergli. Io ti ho dato la penna: certe domande vanno scritte, non dette.",dolcezza:"Avete copiato la ricetta in silenzio: una settimana nessuno ha detto niente. Il silenzio, con me, lo capisci."},threads:['ricetta']},
{id:'s13',chap:'S3',ep:3,kicker:'Sak.3-3 · Pioggia qui',title:'Piove anche nei sogni',text:`Per la prima volta, piove anche a Sakura Eterna. Pioggia vera, grigia, rumorosa. Hana la guarda dalla vetrina come un’estranea.\n\n"Da voi piove sempre?" chiede piano. "Quasi sempre." "E si vive lo stesso?" "Si vive di più, forse."\n\nIl Giardiniere non annaffia: sta fermo sotto la pioggia col cappello in mano. Per la prima volta lo vedi in faccia da lontano: sorride come Takeshi nelle foto vecchie.`,cliff:`La pioggia smette all’improvviso, come spenta. Lui rimette il cappello.`,choiceA:{label:'Gli porti un tè caldo sotto la pioggia',effect:'dolcezza'},choiceB:{label:'«Chi sei?» — stavolta davvero',effect:'coraggio'},level:T(3,19,27,'respiro',-1,'bloom'),letter:`Goccia su vetro — la bambina ci disegna intorno un ombrello.`,ps:{dolcezza:"Gli hai portato il tè caldo sotto la pioggia. Non ha chiesto come lo sapevi: ha bevuto, e basta.",coraggio:"Hai chiesto: chi sei, stavolta davvero. Io taccio: certe domande si fanno due volte, la terza in giardino."},threads:['giardiniere']},
{id:'s14',chap:'S3',ep:4,kicker:'Sak.3-4 · Febbre due',title:'La maestra bambina',text:`La bambina ora insegna a FRULLARE a un bambino del vicinato, con le tue stesse parole: "Il cuore va mosso a cerchi." La guardi e ti manca il fiato: stai guardando te stessa diventare Hana.\n\nHana viva ti stringe il braccio: "Vedi? Il cerchio non si rompe. Si allarga."\n\nQuella sera la bambina ti chiede: "Quando sarò grande come te, mi ricorderò di te?" Non sai cosa rispondere. Dici la verità: "Spero di sì. Io mi ricordo di te da sempre."`,cliff:`Lei annuisce seria, poi ride e ti sporca il naso di schiuma. Patto sigillato.`,choiceA:{label:'Patto di schiuma (naso sporco anche lei)',effect:'dolcezza'},choiceB:{label:'Le prometti di tornare ogni sogno',effect:'coraggio'},level:T(1,19,27,'awa',-1,'bloom'),letter:`Naso di schiuma — foto mentale da tenere per sempre.`,ps:{dolcezza:"Patto di schiuma, naso sporco. Lei ha sporcato anche me: due macchie sulla stessa foto, ed è giusto così.",coraggio:"Le hai promesso di tornare ogni sogno. L'ho sentito da due stanze: torni ogni mattina. Le promesse si onorano."},threads:['aoi-bimba']},
{id:'s15',chap:'S3',ep:5,kicker:'Sak.3-5 · Germoglio',title:'Cosa cresce',text:`I semi del Giardiniere sono germogliati: piantine che profumano di tè prima ancora di avere foglie. Hana le annusa e resta muta un minuto intero.\n\n"Queste... queste le piantava mio padre. Pensavo il seme fosse estinto." Ti guarda con occhi nuovi: "Chi ti manda, Aoi?"\n\nLe racconti del tuo mondo per la centesima volta, ma stavolta aggiungi tutto: Takeshi, la pioggia, i finali. Lei ascolta, poi dice solo: "Che fortuna, due mondi. Che fatica."`,cliff:`I germogli, nella notte, crescono di un dito. Li ha annaffiati qualcuno. Indovina chi.`,choiceA:{label:'Ringrazi il Giardiniere di notte',effect:'dolcezza'},choiceB:{label:'Monti la guardia per vederlo',effect:'coraggio'},level:T(5,20,28,'latte',-1,'bloom'),letter:`Foglia prima — la metti nel quaderno a pagina 1. Ricomincia tutto.`,ps:{dolcezza:"Hai ringraziato il Giardiniere di notte. Lui: ringrazia le foglie. Io non ho detto che ero sveglia anch'io.",coraggio:"Hai montato la guardia per vederlo, e ti sei addormentata sul verandino. Io ti ho coperta. Lui sorrideva."},threads:['ricetta']},
/* S4 — Il Seme */
{id:'s16',chap:'S4',ep:1,kicker:'Sak.4-1 · Guardia',title:'Lo vedi annaffiare',text:`Monti la guardia tutta la notte, nascosta tra i sakura. Alle tre, lui arriva con l’annaffiatoio di rame, e annaffia cantando la canzone di Hana — con le PAROLE, che nemmeno Hana ricorda più.\n\nTi scopre subito, ovviamente. "Bra Brava, sentinella. Vieni, ti insegno la seconda strofa."\n\nLa canta. Parla di un giardiniere che piantò un albero per una ragazza che sposò un altro. "Storia vera?" chiedi. "Le storie vere sono quelle che annaffi."`,cliff:`Ti regala l’annaffiatoio di rame. "È ora che lo tenga una Aoi."`,choiceA:{label:'«Raccontami la storia vera.»',effect:'coraggio'},choiceB:{label:'Annaffi con lui in silenzio',effect:'dolcezza'},level:T(2,20,27,'latte',-1,'bloom',60),letter:`Annaffiatoio di rame — pesa come un segreto ben tenuto.`,ps:{coraggio:"Hai chiesto: raccontami la storia vera. Io c'ero. Non ti ho fermata, ma ti ho fatto il tè mentre parlavi.",dolcezza:"Avete annaffiato in silenzio, e il giardino ha smesso di aspettare. Io guardavo, con il vostro nome in bocca."},threads:['giardiniere']},
{id:'s17',chap:'S4',ep:2,kicker:'Sak.4-2 · Rame',title:'Lezione di rame',text:`Con l’annaffiatoio di rame annaffi i germogli ogni mattina con la bambina. Crescono a vista d’occhio: a metà capitolo sono arbusti, a fine chissà.\n\nHana scherza: "Nel tuo mondo annaffi così anche i debiti?" "Li ho annaffiati di lacrime. Funziona meno."\n\nRidete. Poi lei diventa seria: "Aoi. Se un giorno non mi trovi al bancone, annaffia lo stesso. Le piante non sanno dei lutti." Il cuore ti cade nelle scarpe.`,cliff:`"Nonna, stai bene?" "Benissimo. Ma i sogni finiscono, piccola ladra. Anche i belli. Preparati."`,choiceA:{label:'«Non finirà. Lo impedisco.»',effect:'rabbia'},choiceB:{label:'Annaffi lo stesso, come ordinato',effect:'coraggio'},level:T(0,21,28,'awa',-1,'bloom',60),letter:`Goccia di rame — l’acqua che esce sa di monete antiche e promesse.`,ps:{rabbia:"Hai detto: non finirà, lo impedisco. Ti ho servito il tè in silenzio: non ti ho detto né sì né no.",coraggio:"Hai annaffiato come ordinato, e sei tornata anche il giorno dopo, quando non era più ordinato niente."},threads:['aoi-bimba']},
{id:'s18',chap:'S4',ep:3,kicker:'Sak.4-3 · Arbusto',title:'Il tè che non esiste',text:`Gli arbusti fanno le prime foglie: le assaggiate — sanno di un tè che non esiste in nessun mondo. Lo battezzate "Sakura Eterna", ovviamente, e ne fate tre tazze.\n\nLa prima a Hana: piange. La seconda alla bambina: ride. La terza a te: sa di pioggia E di sole insieme, impossibile e vero.\n\nIl Giardiniere rifiuta la sua: "Io li coltivo, non li bevo. Qualcuno deve restare sobrio, qui."`,cliff:`Hana propone: presentarlo al festival del mondo vero? Ma quale mondo è "vero"?`,choiceA:{label:'«Questo è vero. Ora.»',effect:'dolcezza'},choiceB:{label:'«Sono veri entrambi. Fatica doppia.»',effect:'coraggio'},level:T(3,21,27,'respiro',-1,'bloom',65),letter:`Tre foglie — una per Hana, una per la bambina, una per te. La quarta manca: è per chi legge.`,ps:{dolcezza:"Hai detto: questo è vero, ora. Ho guardato i due mondi insieme, e non ho più contato le differenze.",coraggio:"Hai detto: sono veri entrambi, fatica doppia. Io ho fatto il doppio del tè: è la mia risposta all'impossibile."},threads:['ricetta']},
{id:'s19',chap:'S4',ep:4,kicker:'Sak.4-4 · Sobrio',title:'Chi non beve',text:`Tormentata dalla frase del Giardiniere, lo affronti: perché coltiva un tè che non beve? Lui si siede — per la prima volta, si SIEDE — e ti racconta.\n\n"Ho bevuto una volta. Ho sognato una vita intera: pioggia, una nipote mai nata, un ombrello nero. Mi sono svegliato piangendo e ho deciso: mai più. Io resto sveglio, così i sogni restano vostri."\n\nCapisci tutto e niente. Gli prendi la mano: è calda. I fantasmi non hanno mani calde. O forse sì.`,cliff:`"Bevi con me, stavolta," gli dici. Lui guarda la tazza come un burrone.`,choiceA:{label:'Bevete insieme, mano nella mano',effect:'dolcezza'},choiceB:{label:'Bevi tu per primo, per fargli coraggio',effect:'coraggio'},level:T(1,22,28,'awa',-1,'bloom',65),letter:`Mano calda — prova che i giardinieri esistono davvero.`,ps:{dolcezza:"Avete bevuto insieme, mano nella mano, e un'ora nessuno ha detto niente. Io ero due tavoli più in là.",coraggio:"Hai bevuto per primo, per fargli coraggio. Lui ha bevuto dopo. È l'unico modo che funziona con chi ha paura."},threads:['giardiniere']},
{id:'s20',chap:'S4',ep:5,kicker:'Sak.4-5 · Sogno dentro',title:'Il sogno del Giardiniere',text:`Beve. Si addormenta sulla tua spalla come un bambino. E sogna ad alta voce: parla di pioggia, di una Hana giovane che ride, di una promessa sotto un ombrello di carta.\n\nSono i tuoi ricordi. O i suoi. O gli stessi, da due rive diverse dello stesso fiume.\n\nSi sveglia all’alba, sereno per la prima volta: "Allora esiste davvero, la pioggia. Pensavo di averla inventata per non sentirmi solo."`,cliff:`Da quel giorno annaffia anche di giorno. E ride. Il giardino non l’aveva mai sentito ridere.`,choiceA:{label:'«Benvenuto nel giorno.»',effect:'dolcezza'},choiceB:{label:'Gli mostri come si frulla',effect:'coraggio'},level:T(5,22,28,'latte',-1,'bloom',70),letter:`Risata del giardino — le foglie tremano tutte insieme, applauso verde.`,ps:{dolcezza:"Hai detto: benvenuto nel giorno. Da lì ha annaffiato di giorno, e ha riso. Sapevo che aspettava un permesso.",coraggio:"Gli hai mostrato come si frulla, e ha provato col cucchiaio. Ha fatto schiuma per errore: quella conta."},threads:['aoi-bimba']},
/* S5 — Petali Sopra */
{id:'s21',chap:'S5',ep:1,kicker:'Sak.5-1 · Raccolto',title:'Il primo raccolto',text:`Gli arbusti sono alberi bassi carichi di foglie di Sakura Eterna. Primo raccolto vero: lo fate tutte insieme — Hana, tu, la bambina, il Giardiniere che ride ancora.\n\nNe vengono venticinque tazze. Le numerate. La numero 1 a Hana, la 25 alla bambina. La tua quale sarà? "La prossima," dici. "Ce ne sarà sempre una prossima."\n\nHana ti guarda strano. Quello sguardo lì. Quello dei conti che tornano troppo bene.`,cliff:`"Aoi," dice piano. "Quante tazze mancano, nel tuo mondo?" Non sai rispondere.`,choiceA:{label:'«Tante. Troppe. Le servo tutte.»',effect:'coraggio'},choiceB:{label:'«Quelle giuste. Come queste.»',effect:'dolcezza'},level:T(2,22,27,'latte',-1,'bloom',70),letter:`Tazza n.13 — la tua. Sa di promesse mantenute a metà, benissimo così.`,ps:{coraggio:"Hai detto: tante, troppe, le servo tutte. Io ti ho versato la tazza n.13 e ho detto: una alla volta, ma tutte.",dolcezza:"Hai detto: quelle giuste, come queste. Io ho contato le tazze: tante quante le persone venute."},threads:['ricetta']},
{id:'s22',chap:'S5',ep:2,kicker:'Sak.5-2 · Conti',title:'I conti del sogno',text:`Hana fa i conti del sogno ad alta voce, come si fa coi debiti veri: "Ogni sogno chiede un prezzo. Il nostro qual è?"\n\nNessuno risponde. Mugi — entrambi i Mugi, ormai inseparabili — dormono intrecciati. La risposta dorme con loro: il prezzo è svegliarsi, un giorno.\n\nMa non oggi. Oggi si serve: vassoi altissimi, schiume al 75% o niente, clienti-petali che non aspettano. Il sogno chiede il conto IN schiuma.`,cliff:`Il Giardiniere paga per tutti: pota l’albero vecchio per far luce ai nuovi. Piange potando. Ride piangendo.`,choiceA:{label:'Poti con lui, in silenzio',effect:'coraggio'},choiceB:{label:'Gli tieni la scala e canti',effect:'dolcezza'},level:T(0,23,28,'awa',-1,'bloom',75),letter:`Ramo potato — lo pianti. Tra sessant’anni qualcuno chiederà chi era.`,ps:{coraggio:"Avete potato in silenzio, e le lacrime non si contano. Io ero dietro, e ho contato solo i rami: sette.",dolcezza:"Gli hai tenuto la scala e hai cantato. Lui ha potato cantando: è la cosa più difficile. Io lo sapevo già."},threads:['giardiniere']},
{id:'s23',chap:'S5',ep:3,kicker:'Sak.5-3 · Scala',title:'Tenere la scala',text:`Gli tieni la scala mentre pota e canti la seconda strofa — quella che ti ha insegnato. Lui si ferma, cesoie a mezz’aria.\n\n"La sai." "Me l’hai insegnata tu." "Non te l’ho insegnata. Te la sei ricordata." Scende dalla scala, ti guarda dritto: "Aoi. Io sono... ero... Lascia stare. L’importante è la scala. Tienila sempre, a chi pota."\n\nNon finisce la frase. Non serve. Le scale tenute sono le uniche verità.`,cliff:`Quella notte sogni la pioggia così forte che ti svegli assetata. Bevi sakura. Torni a dormire.`,choiceA:{label:'«So chi sei. Non serve dirlo.»',effect:'dolcezza'},choiceB:{label:'«Dimmelo. Voglio sentirlo.»',effect:'coraggio'},level:T(4,22,27,'respiro',4,'bloom',75),letter:`Scala tenuta — in piedi da sola, adesso. Le cose tenute stanno su.`,ps:{dolcezza:"Hai detto: so chi sei, non serve dirlo. Io ho messo la mano sulla tua, e l'ho saputo anch'io.",coraggio:"Hai detto: dimmelo, voglio sentirlo. Io l'ho detto piano, una volta sola. Poi tè, in silenzio."},threads:['aoi-bimba']},
{id:'s24',chap:'S5',ep:4,kicker:'Sak.5-4 · Penultima qui',title:'La festa dei due mondi',text:`Festa grande: inviti tutti e due i mondi — o meglio, inviti tutti QUI, e brindate ANCHE al mondo di là, con una tazza vuota per la Pioggia.\n\nHana brinda: "A mia nipote, che vive due volte e si lamenta il doppio." Risate. La bambina brinda: "Alla ladra buona!" Il Giardiniere brinda senza parole, alzando l’annaffiatoio.\n\nServi il giro più difficile di sempre: vassoi pieni, schiuma all’80%, mani che sanno. Le mani sognano E vegliano, adesso.`,cliff:`A mezzanotte il vapore si ferma a mezz’aria. Il sogno trattiene il fiato. Domani si sceglie — di nuovo, per sempre.`,choiceA:{label:'«Qualunque alba, la servo.»',effect:'coraggio'},choiceB:{label:'Ballate tutti sotto i petali',effect:'dolcezza'},level:T(3,24,28,'respiro',-1,'bloom',80),letter:`Mezzanotte ferma — il vapore sospeso sembra neve che ha cambiato idea.`,ps:{coraggio:"Hai detto: qualunque alba, la servo. Ho contato le tazze da riempire: tante quante le persone che torneranno.",dolcezza:"Avete ballato sotto i petali, e la bambina è finita sulla testa del Giardiniere. Io ho guardato: e basta."},threads:['ricetta']},
{id:'s25',chap:'S5',ep:5,kicker:'Sak.5-5 · Voto',title:'Il voto dei petali',text:`Alba doppia: sole qui, pioggia di là — le senti entrambe sulla pelle, e non fa male. Fa il solletico dell’infinito.\n\nHana, la bambina e il Giardiniere ti aspettano in giardino con due tazze: una di sakura, una d’acqua di pioggia conservata in un barattolo dal giorno che piovve qui.\n\n"Non devi scegliere il mondo," dice Hana. "Devi promettere come starci. Il voto dei petali: dillo forte." Prendi il chasen. Le mani non tremano. Non tremano in nessun mondo, ormai.`,cliff:`Bevi prima una, poi l’altra. Sanno della stessa cosa, da due rive. Il voto sale col vapore.`,choiceA:{label:'«Ci sto con tutto. Sempre.»',effect:'dolcezza'},choiceB:{label:'«Ci sto. E torno. Sempre.»',effect:'coraggio'},level:T(1,24,28,'awa',-1,'bloom',85),letter:`Voto dei petali — detto forte, udito ovunque. Anche nella Pioggia.`,ps:{dolcezza:"Hai detto: ci sto con tutto, sempre. Io ho preso una tazza da te, e l'abbiamo bevuta col vapore che saliva.",coraggio:"Hai detto: ci sto, e torno, sempre. Ho contato le volte che sei tornata: sono tutte, non ne manca una."},threads:['giardiniere']},
];
