const YSTORY = [
{id:'y1',chap:'Y1',ep:1,kicker:'Yok.1-1 · Cancello',title:'Tè oltrepassa',text:`Mezzanotte al tempio. Tè fissa il cancello di pietra e miagola una volta — il cancello si apre su scale che scendono. Sotto: un villaggio intero sotto una luna fissa, bancarelle accese, profumo di tè e muschio.\n\n"Chi entra col gatto è ospite," dice una voce senza volto. "Chi entra senza tè è cena. Tu hai entrambi, vedo." Una locandiera senza lineamenti ti porge una maschera neutra: "Per le prime ore. Poi scegli la tua."\n\nMugi trema nella borsa. Gli sussurri: "Anch’io."`,cliff:`Sulla locanda, un’insegna: "A chi serve di notte, la notte serve."`,choiceA:{label:'Indossi la maschera neutra',effect:'coraggio'},choiceB:{label:'«Resto a faccia scoperta.»',effect:'dolcezza'},level:T(1,15,25,'latte',-1,'ink'),letter:`Maschera neutra — liscia come un "ciao" non detto.`,ps:{coraggio:"La maschera indossata pesa come un debito gentile: si restituisce con un inchino, e il viso torna suo.",dolcezza:"Restare a faccia scoperta costa quanto una maschera, e dice una cosa sola: questa faccia resta, e basta."},threads:['maschera']},
{id:'y2',chap:'Y1',ep:2,kicker:'Yok.1-2 · Locanda',title:'La Padrona',text:`La Padrona Senza Volto ti assume al banco del tè: sei l’unica viva nel raggio di tre sogni, e i vivi fanno la schiuma migliore — "sa di sveglia".\n\nIl vassoio, però, si macchia da solo: inchiostro vivo che avanza ogni tre mosse e inghiotte le tessere. Lo pulisci coi match vicini, in fretta, ridendo per non piangere.\n\n"Bra Brava," dice la Padrona. "Hana faceva così. Veloce e allegra." Si blocca: "Hana... perché ho detto Hana?"`,cliff:`Dietro il bancone, una vecchia recensione ingiallita: stroncatura di un chashitsu, firmata con un nome famoso.`,choiceA:{label:'Leggi la firma',effect:'coraggio'},choiceB:{label:'La rimetti a posto senza leggere',effect:'dolcezza'},level:T(3,16,26,'respiro',-1,'ink'),letter:`Macchia pulita — l’inchiostro sa di sampietrini bagnati.`,ps:{coraggio:"La firma si legge una volta sola: poi diventa una macchia, e le macchie non si riutilizzano.",dolcezza:"Rimetterla a posto senza leggere è l'unico modo di tenere una locanda: la verità aspetta, l'inchiostro no."},threads:['sogni']},
{id:'y3',chap:'Y1',ep:3,kicker:'Yok.1-3 · Firma',title:'La critica',text:`La firma è di una critica gastronomica temutissima, ritiratasi dopo aver stroncato — per invidia, ammise anni dopo — proprio il chashitsu Hana. Hana le rispose invitandola a bere. Diventarono quasi amiche.\n\n"Ho passato trent’anni a prestare volti," dice la Padrona, "perché col mio avevo fatto male." Ti porge la maschera più bella: "Tienla. Tu il volto lo usi bene."\n\nRifiutarla sarebbe crudele. Accettarla, un patto. Prendi la maschera e le prometti una tazza all’alba.`,cliff:`"All’alba non ci sono mai," ride lei. "Ma la tazza lasciala lo stesso."`,choiceA:{label:'«L’alba ti troverà.»',effect:'dolcezza'},choiceB:{label:'«Allora bevo io per due.»',effect:'coraggio'},level:T(0,17,26,'awa',-1,'ink'),letter:`Maschera bella — pesa come un perdono accettato.`,ps:{dolcezza:"L'alba non trova nessuno, al Villaggio: prende in prestito un'ora e lascia il debito aperto.",coraggio:"Bere per due è la regola del villaggio: la tazza raddoppia, la notte no, e il sonno si divide."},threads:['lanterna']},
{id:'y4',chap:'Y1',ep:4,kicker:'Yok.1-4 · Russare',title:'Baku',text:`Sotto il tuo banco dorme un tasso grosso come un armadio: Baku, mangiasogni. Russa così forte che le tazze tremano — e i clienti adorano il "sottofondo".\n\n"Diglielo, il tuo incubo," suggerisce la Padrona. "Quello con Hana che chiama e tu non trovi la porta." Come fa a saperlo? Qui i sogni si sentono russare attraverso i muri.\n\nGlielo racconti tutto d’un fiato. Baku, dormendo, allunga una zampa e ti accarezza la caviglia. Il russare cambia tono: sta masticando.`,cliff:`Ti svegli — avevi dormito in piedi? — più leggera di tre notti.`,choiceA:{label:'«Grazie, Baku. Tieni il resto.»',effect:'dolcezza'},choiceB:{label:'Gli lasci un mochi sul naso',effect:'coraggio'},level:T(2,17,26,'latte',-1,'ink'),letter:`Mochi mangiato — dal naso in su, senza svegliarsi. Talento.`,ps:{dolcezza:"Grazie si dice una volta sola al tasso, e il resto si tiene per la notte: è il suo stipendio.",coraggio:"Un mochi sul naso è l'unico inchino che Baku accetta: riceve omaggi solo da sopra, e dorme meglio."},threads:['maschera']},
{id:'y5',chap:'Y1',ep:5,kicker:'Yok.1-5 · Kitsune',title:'Posta tra mondi',text:`Un volpacchiotto col berretto da postino inciampa nel tuo banco: è il Kitsune Postino, corriere tra i mondi. "Lettera per... Aoi? Ne ho tre, di Aoi diverse. Rete pessima, qui."\n\nUna è per te: mittente Sōma, mondo Pioggia. "Il nipote ha fatto il giro da solo. Pensavo ti facesse piacere saperlo. Il tuo tè manca anche qui sotto."\n\nPiangi ridendo. Il Kitsune finge di guardare altrove e ti lascia un biscotto a forma di luna.`,cliff:`"Se mai vuoi spedire SOGNI," dice, "io li porto. I sogni pesano meno delle lettere."`,choiceA:{label:'Spedisci un sogno a Hana',effect:'dolcezza'},choiceB:{label:'Spedisci un incubo a Baku (da mangiare)',effect:'coraggio'},level:T(5,18,27,'respiro',-1,'ink'),letter:`Biscotto-luna — sa di burro e di posta arrivata.`,ps:{dolcezza:"Un sogno spedito a Hana pesa meno di una lettera, e arriva in tre giorni: i sogni viaggiano meglio di notte.",coraggio:"L'incubo spedito a Baku si mangia in piedi, e il tasso ringrazia con un rombo. Poi dorme leggero."},threads:['sogni']},
{id:'y6',chap:'Y2',ep:1,kicker:'Yok.2-1 · Parata',title:'La sfilata',text:`Notte di parata: cento spiriti sfilano con lanterne, il tuo banco è l’unica tappa "per vivi e stanchi". Servi senza fermarti mentre tutto sfila.\n\nTra i carri, uno fermo: sopra, una lanterna SPENTA con sopra scritto il tuo nome. Aoi. La tua grafia? No: quella di Hana.\n\nLa Padrona impallidisce — cosa impossibile senza volto, eppure succede: "Quella lanterna aspetta da sessant’anni. Non toccarla finché non sai il perché."`,cliff:`Il carro riparte da solo. La lanterna spenta ti segue con lo sguardo. Le lanterne non hanno occhi. Questa sì.`,choiceA:{label:'La segui tra la folla',effect:'coraggio'},choiceB:{label:'Torni al banco (il dovere prima)',effect:'dolcezza'},level:T(1,19,27,'awa',-1,'ink'),letter:`Coriandolo di parata — a forma di piccole lune. Ne tieni una manciata.`,ps:{coraggio:"Seguire la lanterna nella folla costa il turno intero: si torna con i piedi sporchi e gli occhi aperti.",dolcezza:"Tornare al banco prima che la sfilata finisca è il dovere, e il dovere al Villaggio non si negozia."},threads:['lanterna']},
{id:'y7',chap:'Y2',ep:2,kicker:'Yok.2-2 · Nome',title:'Il nome che scotta',text:`Baku ti spiega le lanterne spente, russando a metà: "Aspettano il nome vero di qualcuno. I nomi veri scottano, per questo nessuno li dice... e le lanterne restano spente... ronf..."\n\nIl tuo nome, sulla lanterna, è scritto da Hana. Quale nome aspetta, allora? Il tuo? Il suo? Quello del Giardiniere, che qui tutti conoscono e nessuno nomina?\n\nServi il turno più tosto finora: inchiostro che corre, schiuma al 60% o la parata ti fischia. Le mani sanno. Le mani sanno sempre, ormai.`,cliff:`A fine turno la lanterna è più vicina. Non l’hai vista muoversi. Nessuno l’ha vista muoversi.`,choiceA:{label:'«Il mio nome è Aoi. Accenditi.»',effect:'coraggio'},choiceB:{label:'Le offri tè invece di nomi',effect:'dolcezza'},level:T(0,20,27,'latte',-1,'ink',60),letter:`Fischio di parata — in realtà erano applausi. Gli spiriti fischiano ridendo.`,ps:{coraggio:"Il nome è la chiave e la lanterna la usa: detta una volta sola, e per un attimo il villaggio è illuminato.",dolcezza:"Il tè, alla lanterna, si offre senza nome: bere insieme non accende niente, e non è poco."},threads:['maschera']},
{id:'y8',chap:'Y2',ep:3,kicker:'Yok.2-3 · Doppio',title:'Due Aoi',text:`Nella folla vedi TE STESSA: un’altra Aoi con la maschera bella, che serve a un altro banco. Vi guardate. Vi inchinate. Nessuna delle due scappa.\n\n"Sei quella della Pioggia o quella del Sogno?" chiede lei. "Pioggia." "Io Sakura. Ci manca quella dell’Estate, poi siamo al completo." Ridete come sorelle.\n\nVi scambiate una tessera portafortuna: lei ti dà un petalo, tu le dai una goccia (di sudore, dicono i maligni; di pioggia, dici tu).`,cliff:`La lanterna spenta, lontana, sembra accendersi di un millimetro. O è la parata che abbaglia?`,choiceA:{label:'«Ci vediamo a ogni parata.»',effect:'dolcezza'},choiceB:{label:'Le chiedi del Giardiniere',effect:'coraggio'},level:T(3,20,27,'respiro',-1,'ink',60),letter:`Petalo scambiato — profuma di un mondo dove non piove mai.`,ps:{dolcezza:"Ogni parata è un appuntamento senza posto fisico: ci si vede dove finisce la musica, e ci si riconosce.",coraggio:"Del Giardiniere si può chiedere solo una cosa per notte, e le risposte non tornano mai nel posto giusto."},threads:['sogni']},
{id:'y9',chap:'Y2',ep:4,kicker:'Yok.2-4 · Teatro',title:'Il palco vuoto',text:`La Padrona ti porta al Teatro Vuoto: cinquecento posti, sipario chiuso, polvere di secoli. "Qui si raccontano storie vere a chi non dorme mai. Tocca a te, domani."\n\nDovrai mettere in scena la storia di Hana e Takeshi. Con che faccia? Con la tua, dice la Padrona, prestandoti il suo volto migliore "per le scene difficili".\n\nProvi tutta la notte col gatto Tè come unico spettatore. Lui sbadiglia alle scene tristi e fa le fusa a quelle dolci. Critico perfetto.`,cliff:`Dietro il sipario, qualcuno piange piano. Non è tristezza: è prova generale del pubblico.`,choiceA:{label:'Provi fino all’alba (che non viene)',effect:'coraggio'},choiceB:{label:'Dormi un’ora sulla spalla di Baku',effect:'dolcezza'},level:T(2,21,27,'awa',-1,'ink',65),letter:`Biglietto del Teatro — posto H-ANA, prima fila. Tuo, per sempre.`,ps:{coraggio:"Provare fino all'alba, al Teatro, è come contare le stelle: si prova, e l'alba non viene mai.",dolcezza:"Dormire un'ora sulla spalla di Baku è l'unico sonno che non chiede riscatto: lui sogna, tu riposi."},threads:['lanterna']},
{id:'y10',chap:'Y2',ep:5,kicker:'Yok.2-5 · Prove',title:'Hana e Takeshi (prove)',text:`Prove generali: racconti i sessant’anni in un’ora. Il koicha del ’64 lo prepari davvero, sul palco, e il profumo fa piangere tre file.\n\nBaku mangia gli incubi del pubblico durante l’intervallo e russa nel finale — applauso a parte. La Padrona, in platea, si toglie la maschera per la prima volta: sotto c’è un volto normale, stanco, buono.\n\n"Domani sera si va in scena," dice. "E la lanterna verrà a vedere. Lo sento."`,cliff:`La lanterna spenta è già lì, in ultima fila. Puntuale come un rimorso.`,choiceA:{label:'«Domani. Per tutti.»',effect:'coraggio'},choiceB:{label:'Le porti tè in ultima fila',effect:'dolcezza'},level:T(4,21,27,'latte',4,'ink',65),letter:`Volto della Padrona — normale, stanco, buono. Il più bello.`,ps:{coraggio:"Domani, per tutti: è la battuta che chiude le prove al Villaggio. La plateia espira, e la notte si accorcia.",dolcezza:"Portare il tè in ultima fila è l'unico posto dove la Padrona beve: il resto del teatro lo ascolta soltanto."},threads:['maschera']},
{id:'y11',chap:'Y3',ep:1,kicker:'Yok.3-1 · Sipario',title:'Si va in scena',text:`Sipario. Cinquecento spiriti. Racconti Hana ventenne e Takeshi ragazzo, l’ombrello di carta, le lettere, la guerra, i quarant’anni di carta.\n\nL’inchiostro invade il palco-vassoio come non mai: macchie ovunque, schiuma al 70% o la storia affoga. Servi e reciti insieme, mani e voce, senza rete.\n\nA metà spettacolo capisci: non stai recitando. Stai RICORDANDO per tutti loro.`,cliff:`Dalla platea, un singhiozzo collettivo. Anche i fantasmi hanno il nodo in gola, a quanto pare.`,choiceA:{label:'Continui senza guardare (voce ferma)',effect:'coraggio'},choiceB:{label:'Guardali e sorridi tra le lacrime',effect:'dolcezza'},level:T(1,22,27,'awa',-1,'ink',70),letter:`Nodo in gola — cinquecento, tutti insieme. Record del villaggio.`,ps:{coraggio:"Continuare senza guardare, con la voce ferma, è il mestiere: gli spiriti capiscono, e applaudono di più.",dolcezza:"Guardarli e sorridere tra le lacrime è come bere dal bicchiere rotto: si beve lo stesso, e con più sete."},threads:['sogni']},
{id:'y12',chap:'Y3',ep:2,kicker:'Yok.3-2 · Intervallo',title:'L’intervallo di Baku',text:`Intervallo: Baku fa il suo numero — mangia in diretta l’incubo di uno spettatore (un esame mai dato, classico) e scoreggia scintille verdi. Standing ovation.\n\nPoi tocca al tuo, di incubo: quello con Hana che chiama e tu non trovi la porta. Lo racconti al microfono invece di darmelo? Baku ti guarda: "Dillo. Poi lo mangio. Poi non c’è più."\n\nLo dici. Lui lo mangia. Rutta una stellina. Non c’è più. Non c’è davvero più — controlli, la mattina dopo, ed è vero.`,cliff:`In camerino trovi un biglietto: "Grazie per la cena. — B." Accanto, un mochi rosicchiato a forma di luna.`,choiceA:{label:'«Il prossimo lo divido con te.»',effect:'dolcezza'},choiceB:{label:'Gli affidi tutti gli incubi futuri',effect:'coraggio'},level:T(5,22,27,'respiro',-1,'ink',70),letter:`Stellina ruttata — la tieni in tasca. Pesa come niente. Vale tutto.`,ps:{dolcezza:"Il prossimo lo divido con te: all'intervallo le porzioni che restano si mettono in tasca, e durano di più.",coraggio:"Gli incubi futuri si affidano come pacchi: non si paga la consegna, si paga il coraggio di averli contati."},threads:['lanterna']},
{id:'y13',chap:'Y3',ep:3,kicker:'Yok.3-3 · Atto secondo',title:'L’atto della pioggia',text:`Secondo atto: la pioggia. Sul palco fai piovere davvero — secchi d’acqua dai ballatoi, tecnici-spirito efficientissimi. Il pubblico impazzisce di gioia: qui non piove da secoli.\n\nRacconti Takeshi sotto la pioggia vera, l’ultimo tè, l’ombrello piegato. La lanterna in ultima fila trema. Trema forte.\n\nLa schiuma deve reggere il 75% sotto la pioggia di scena. Le mani fanno da sole. Tu guardi solo la lanterna.`,cliff:`Un bagliore, dentro il vetro spento. Piccolo. Come un’alba in miniatura.`,choiceA:{label:'«Forza. Quasi.» (sottovoce)',effect:'coraggio'},choiceB:{label:'Le dedichi la scena, a voce alta',effect:'dolcezza'},level:T(0,23,28,'latte',-1,'ink',75),letter:`Goccia di scena — vera, salata, tua. La migliore.`,ps:{coraggio:"Forza, quasi: si dice al sipario, non agli attori. Al Villaggio il sipario va incoraggiato.",dolcezza:"Dedicare la scena a voce alta, in teatro, si chiama offrire il nome: e i nomi, al Villaggio, sono valuta."},threads:['maschera']},
{id:'y14',chap:'Y3',ep:4,kicker:'Yok.3-4 · Bagliore',title:'Cosa brucia',text:`Il bagliore cresce: dentro la lanterna c’è un nome che brucia piano da sessant’anni. È il nome che Hana non disse mai ad alta voce — quello vero del Giardiniere? Quello di Takeshi prima della guerra? Il tuo?\n\nLa Padrona sale sul palco — senza maschera — e dice al pubblico: "Questa storia la finiamo insieme. Ognuno dica un nome che non dice mai."\n\nCinquecento nomi sussurrati fanno più luce di cinquecento lanterne. La tua dice il suo nome ad alta voce, per tutti.`,cliff:`La lanterna si accende. Tutta. Il teatro diventa giorno per tre secondi.`,choiceA:{label:'Piangi in piedi, inchinandoti',effect:'dolcezza'},choiceB:{label:'Ridi in piedi, inchinandoti',effect:'coraggio'},level:T(3,24,28,'respiro',-1,'ink',80),letter:`Tre secondi di giorno — in tasca con la stellina. Scorta di luce.`,ps:{dolcezza:"Piangere in piedi ringrazia l'illuminazione: per tre secondi, il teatro ti restituisce il viso.",coraggio:"Ridere in piedi, inchinandandoti, è la controfigura: il giorno dura tre secondi e si festeggia come un anno."},threads:['sogni']},
{id:'y15',chap:'Y3',ep:5,kicker:'Yok.3-5 · Alba',title:'La lanterna accesa',text:`Finale: la lanterna accesa viene sul palco da sola e si posa tra le tue mani. Dentro, un biglietto con la grafia di Hana: "Per chi serve di notte. Accendi gli altri."\n\nLa Padrona ti offre il teatro: "Resta. Cantastorie residente. Pagamento: applausi e mochi." Baku russa approvando. Il Kitsune ha già pronto un contratto (diffida dei contratti dei kitsune).\n\nMa l’alba — vera, del tuo mondo — sta per sorgere. Senti il profumo di pioggia vera da sopra il cancello. Devi scegliere dove bere il prossimo tè.`,cliff:`Tè ti guarda. Mugi ti guarda. Due gatti, due mondi, una sola Aoi.`,choiceA:{label:'🏮 MASCHERA — resto cantastorie, torno a ogni luna nuova',effect:'finale-maschera'},choiceB:{label:'🌅 ALBA — torno all’alba vera con la lanterna accesa',effect:'finale-alba'},level:T(2,25,28,'awa',-1,'ink',85),letter:`Lanterna accesa — luce per tornare. O per restare. La porti comunque.`,finaleNote:'Ultima scelta della Notte Yokai: RESTARE cantastorie o TORNARE all’alba con la luce. 🏮',threads:['lanterna','maschera','sogni']},
];
const YENDINGS = {
  'finale-maschera': { title: 'Finale: MASCHERA 🏮', text: `Resti. Ogni luna nuova torni al Teatro Vuoto e racconti una storia vera: la tua, quella di Hana, quella di chiunque abbia bisogno di essere ricordato.\n\nLa Padrona ti ha dato la maschera più bella "per le scene difficili". Non la usi quasi mai. Il tuo volto basta, ormai.\n\nNel mondo di sopra è sempre notte fonda quando manchi — ma torni sempre prima che il tè si freddi. I due mondi bevono insieme, ormai. Come due tazze della stessa teiera.` },
  'finale-alba': { title: 'Finale: ALBA 🌅', text: `Torni all’alba vera con la lanterna accesa in mano. A Kyoto piove, e la pioggia sulla lanterna fa un suono che è quasi musica.\n\nAppendi la lanterna all’ingresso del chashitsu: da allora non si è mai spenta. I clienti dicono che fa luce anche di giorno. Yuki ci ha disegnato sopra una tazza.\n\nBaku ti ha lasciato un biglietto: "Se sogni male, urlami. Sento anche da sotto." Dormi benissimo, da allora. Quasi sempre.` },
};
